def get_random_bible_verse(book_ids=None, **_extra):
    import json, os, datetime, random, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0476000" if __import__("os").path.isdir("./environment_mix/0476000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    translations = _load("translations.json")
    books = _load("books.json")
    verses = _load("verses.json")
    reqs = _load("passage_requests.json")

    def _new_req_id():
        return "breq_" + secrets.token_hex(12)

    # Always log a request row for this tool
    req_row = {
        "id": _new_req_id(),
        "request_type": "random_verse",
        "translation_code": "web",
        "translation_id": None,
        "input_reference": None,
        "input_book_ids": book_ids,
        "resolved_book_codes": None,
        "parsed_start_chapter": None,
        "parsed_start_verse": None,
        "parsed_end_chapter": None,
        "parsed_end_verse": None,
        "result_verse_ids": None,
        "status": "received",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    def _finalize(status, error_message=None, verse_ids=None, resolved_codes=None):
        req_row["status"] = status
        req_row["error_message"] = error_message
        req_row["result_verse_ids"] = verse_ids
        req_row["resolved_book_codes"] = resolved_codes
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        reqs.append(req_row)
        _save("passage_requests.json", reqs)

    # Resolve implicit translation 'web' (serveable: active/deprecated)
    tr = None
    for t in translations:
        if isinstance(t, dict) and t.get("code") == "web" and t.get("status") in ("active", "deprecated"):
            tr = t
            break
    if not tr:
        _finalize("error", "translation 'web' is not available")
        return _err("UNAUTHORIZED", "No available translation context could serve this request.")

    req_row["translation_id"] = tr.get("id")
    tr_id = tr.get("id")

    # Parse/validate book_ids per business rules
    scope = None
    requested_codes = None
    raw = book_ids
    if raw is None:
        scope = "ALL"
    elif not isinstance(raw, str):
        _finalize("invalid_request", "book_ids must be a string or null")
        return _err("VALIDATION_ERROR", "book_ids must be a string or null.")
    else:
        s = raw.strip()
        if s == "":
            scope = "ALL"  # empty/whitespace treated as null
        else:
            up = s.upper()
            if up in ("OT", "NT"):
                scope = up
            else:
                parts = [p.strip().upper() for p in s.split(",")]
                # Any empty segment is invalid_request (unknown/empty book IDs)
                if any(p == "" for p in parts):
                    _finalize("invalid_request", "book_ids contains empty book code segment")
                    return _err("VALIDATION_ERROR", "book_ids contains an empty/invalid book code.")
                requested_codes = parts
                scope = "LIST"

    # Build eligible active books in this translation
    active_books = [b for b in books if isinstance(b, dict) and b.get("translation_id") == tr_id and b.get("status") == "active"]
    by_code = {b.get("book_code"): b for b in active_books if isinstance(b.get("book_code"), str)}

    resolved_codes = None
    eligible_book_ids = None

    if scope == "ALL":
        resolved_codes = sorted([c for c in by_code.keys() if isinstance(c, str)])
        eligible_book_ids = {b.get("id") for b in active_books if b.get("id")}
    elif scope in ("OT", "NT"):
        eligible = [b for b in active_books if b.get("testament") == scope]
        resolved_codes = sorted([b.get("book_code") for b in eligible if isinstance(b.get("book_code"), str)])
        eligible_book_ids = {b.get("id") for b in eligible if b.get("id")}
    else:  # LIST
        unknown = [c for c in requested_codes if c not in by_code]
        if unknown:
            msg = "unknown book code(s) in list: " + ",".join(unknown)
            _finalize("invalid_request", msg, resolved_codes=None)
            return _err("VALIDATION_ERROR", msg)
        resolved_codes = requested_codes[:]
        eligible_book_ids = {by_code[c].get("id") for c in requested_codes if by_code[c].get("id")}

    # Eligible verses: active, in translation, in eligible books
    eligible_verses = [
        v for v in verses
        if isinstance(v, dict)
        and v.get("translation_id") == tr_id
        and v.get("status") == "active"
        and v.get("book_id") in eligible_book_ids
        and isinstance(v.get("text"), str)
        and v.get("text") != ""
    ]

    if not eligible_verses:
        # Real behavior: request is fulfilled with empty? Business rules say not_found status.
        _finalize("not_found", "no eligible verses found for requested scope", verse_ids=None, resolved_codes=resolved_codes)
        return {
            "translation": {"id": tr.get("id"), "code": tr.get("code"), "name": tr.get("name"), "language": tr.get("language"), "status": tr.get("status")},
            "verse": None,
            "request": {"id": req_row["id"], "status": "not_found"},
        }

    chosen = random.choice(eligible_verses)

    # Find book code/name for reference formatting (do not error if missing metadata)
    book_row = None
    for b in active_books:
        if b.get("id") == chosen.get("book_id"):
            book_row = b
            break

    book_code = book_row.get("book_code") if book_row else None
    book_name = book_row.get("name") if book_row else None
    chap = chosen.get("chapter_number")
    vsn = chosen.get("verse_number")
    ref = None
    if isinstance(book_code, str) and isinstance(chap, int) and isinstance(vsn, int):
        ref = f"{book_code} {chap}:{vsn}"

    _finalize("fulfilled", None, verse_ids=[chosen.get("id")], resolved_codes=resolved_codes)

    return {
        "translation": {"id": tr.get("id"), "code": tr.get("code"), "name": tr.get("name"), "language": tr.get("language"), "status": tr.get("status")},
        "verse": {
            "id": chosen.get("id"),
            "reference": ref,
            "book": {"id": chosen.get("book_id"), "code": book_code, "name": book_name},
            "chapter_number": chap,
            "verse_number": vsn,
            "text": chosen.get("text"),
            "paragraph_break_before": bool(chosen.get("paragraph_break_before")),
        },
        "request": {"id": req_row["id"], "status": "fulfilled", "latency_ms": int((time.time() - t0) * 1000)},
    }

def get_bible_verse(reference, translation="web", **_extra):
    import json, os, datetime, re, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0476000" if __import__("os").path.isdir("./environment_mix/0476000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    translations = _load("translations.json")
    books = _load("books.json")
    chapters = _load("chapters.json")
    verses = _load("verses.json")
    reqs = _load("passage_requests.json")

    def _new_req_id():
        return "breq_" + secrets.token_hex(12)

    def _persist_req(req_row):
        reqs.append(req_row)
        _save("passage_requests.json", reqs)

    def _update_req(req_row, status, error_message=None, verse_ids=None, resolved_codes=None, parsed=None):
        # Enforce passage_requests lifecycle: received -> terminal
        if req_row.get("status") != "received":
            return
        if status not in ("fulfilled", "not_found", "invalid_request", "error"):
            status = "error"
        req_row["status"] = status
        req_row["error_message"] = error_message
        req_row["result_verse_ids"] = verse_ids
        req_row["resolved_book_codes"] = resolved_codes
        if parsed:
            req_row["parsed_start_chapter"] = parsed.get("start_chapter")
            req_row["parsed_start_verse"] = parsed.get("start_verse")
            req_row["parsed_end_chapter"] = parsed.get("end_chapter")
            req_row["parsed_end_verse"] = parsed.get("end_verse")
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("passage_requests.json", reqs)

    # Validate inputs
    if not isinstance(reference, str) or not reference.strip():
        # still log an invalid_request per business rule
        translation_code = "web" if translation is None else (translation.strip().lower() if isinstance(translation, str) else "web")
        req_row = {
            "id": _new_req_id(),
            "request_type": "reference_lookup",
            "translation_code": translation_code if isinstance(translation_code, str) else "web",
            "translation_id": None,
            "input_reference": reference if isinstance(reference, str) else None,
            "input_book_ids": None,
            "resolved_book_codes": None,
            "parsed_start_chapter": None,
            "parsed_start_verse": None,
            "parsed_end_chapter": None,
            "parsed_end_verse": None,
            "result_verse_ids": None,
            "status": "received",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        _persist_req(req_row)
        _update_req(req_row, "invalid_request", "could not parse reference: reference must be a non-empty string")
        return _err("VALIDATION_ERROR", "reference is required and must be a non-empty string.")

    if translation is None:
        translation_code = "web"
    elif not isinstance(translation, str) or not translation.strip():
        translation_code = "web"
        # Parameter schema says translation is string; treat invalid as validation error (and log)
        req_row = {
            "id": _new_req_id(),
            "request_type": "reference_lookup",
            "translation_code": "web",
            "translation_id": None,
            "input_reference": reference,
            "input_book_ids": None,
            "resolved_book_codes": None,
            "parsed_start_chapter": None,
            "parsed_start_verse": None,
            "parsed_end_chapter": None,
            "parsed_end_verse": None,
            "result_verse_ids": None,
            "status": "received",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        _persist_req(req_row)
        _update_req(req_row, "invalid_request", "could not parse reference: translation must be a non-empty string")
        return _err("VALIDATION_ERROR", "translation must be a non-empty string.")
    else:
        translation_code = translation.strip().lower()

    # Resolve translation (servable: active or deprecated). Disabled should not be exposed.
    tr = None
    for t in translations:
        if isinstance(t, dict) and t.get("code") == translation_code and t.get("status") in ("active", "deprecated"):
            tr = t
            break

    req_row = {
        "id": _new_req_id(),
        "request_type": "reference_lookup",
        "translation_code": translation_code,
        "translation_id": tr.get("id") if tr else None,
        "input_reference": reference,
        "input_book_ids": None,
        "resolved_book_codes": None,
        "parsed_start_chapter": None,
        "parsed_start_verse": None,
        "parsed_end_chapter": None,
        "parsed_end_verse": None,
        "result_verse_ids": None,
        "status": "received",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    _persist_req(req_row)

    # Parse reference: <book> <chapter>:<verse>[-<end>] where end is <verse> or <chapter>:<verse>
    # Accept flexible book tokens (e.g., "rom", "1 cor", "song of solomon") and map by matching known book codes/names.
    ref = reference.strip()
    m = re.match(r"^\s*(.+?)\s+(\d+)\s*:\s*(\d+)\s*(?:-\s*(\d+)(?:\s*:\s*(\d+))?|\s*-\s*(\d+)\s*)?\s*$", ref, flags=re.IGNORECASE)
    # Above regex is intentionally permissive but ambiguous; we'll also support a more explicit parse:
    if not m:
        # Another common form: "ROM 12:2-13" or "ROM 12:2-13:5" (end chapter can appear)
        m2 = re.match(r"^\s*(.+?)\s+(\d+)\s*:\s*(\d+)\s*(?:-\s*(?:(\d+)\s*:\s*)?(\d+))?\s*$", ref, flags=re.IGNORECASE)
        if not m2:
            _update_req(req_row, "invalid_request", "could not parse reference: expected 'Book Chapter:Verse' optionally with '-EndVerse' or '-EndChapter:EndVerse'")
            return _err("VALIDATION_ERROR", "could not parse reference", reference=reference)
        book_part = m2.group(1).strip()
        start_ch = int(m2.group(2))
        start_vs = int(m2.group(3))
        end_ch = int(m2.group(4)) if m2.group(4) else None
        end_vs = int(m2.group(5)) if m2.group(5) else None
    else:
        # This match is less reliable; fall back to explicit groups if possible
        m2 = re.match(r"^\s*(.+?)\s+(\d+)\s*:\s*(\d+)\s*(?:-\s*(?:(\d+)\s*:\s*)?(\d+))?\s*$", ref, flags=re.IGNORECASE)
        if not m2:
            _update_req(req_row, "invalid_request", "could not parse reference: expected 'Book Chapter:Verse' optionally with '-EndVerse' or '-EndChapter:EndVerse'")
            return _err("VALIDATION_ERROR", "could not parse reference", reference=reference)
        book_part = m2.group(1).strip()
        start_ch = int(m2.group(2))
        start_vs = int(m2.group(3))
        end_ch = int(m2.group(4)) if m2.group(4) else None
        end_vs = int(m2.group(5)) if m2.group(5) else None

    if start_ch < 1 or start_vs < 1:
        _update_req(req_row, "invalid_request", "could not parse reference: chapter and verse must be >= 1", parsed={"start_chapter": start_ch, "start_verse": start_vs})
        return _err("VALIDATION_ERROR", "chapter and verse must be >= 1")

    if end_ch is None and end_vs is None:
        end_ch = start_ch
        end_vs = start_vs
    elif end_ch is None and end_vs is not None:
        end_ch = start_ch
    elif end_ch is not None and end_vs is None:
        _update_req(req_row, "invalid_request", "could not parse reference: missing end verse in range", parsed={"start_chapter": start_ch, "start_verse": start_vs})
        return _err("VALIDATION_ERROR", "invalid range: missing end verse")

    if end_ch < 1 or end_vs < 1:
        _update_req(req_row, "invalid_request", "could not parse reference: end chapter and verse must be >= 1")
        return _err("VALIDATION_ERROR", "end chapter and verse must be >= 1")
    if (end_ch, end_vs) < (start_ch, start_vs):
        _update_req(req_row, "invalid_request", "could not parse reference: end before start", parsed={"start_chapter": start_ch, "start_verse": start_vs, "end_chapter": end_ch, "end_verse": end_vs})
        return _err("VALIDATION_ERROR", "invalid range: end before start")

    # Resolve book by translation + (book_code OR name match). Must be active.
    tr_id = tr.get("id") if tr else None
    # If translation doesn't exist/servable, treat as not_found (not invalid_request), without exposing disabled metadata.
    if not tr_id:
        _update_req(req_row, "not_found", "translation not found or not available")
        return {
            "translation": {"code": translation_code, "found": False},
            "reference": {"input": reference, "found": False},
            "passage": {"verses": [], "text": ""},
            "request": {"id": req_row["id"], "status": "not_found", "latency_ms": int((time.time() - t0) * 1000)},
        }

    # Build candidates in this translation
    candidates = [b for b in books if isinstance(b, dict) and b.get("translation_id") == tr_id and b.get("status") == "active"]
    book_code = None
    bp_norm = re.sub(r"\s+", " ", book_part.strip()).upper()
    # Prefer exact book_code match if it looks like a canonical code
    if re.fullmatch(r"[A-Z0-9]{2,10}", bp_norm):
        for b in candidates:
            if b.get("book_code") == bp_norm:
                book_code = b.get("book_code")
                book_row = b
                break
        else:
            book_row = None
    else:
        # Match by name/short_name (case-insensitive), tolerant of punctuation
        def _slug(s):
            s = (s or "")
            s = re.sub(r"[^A-Za-z0-9]+", " ", s).strip().lower()
            return re.sub(r"\s+", " ", s)
        target = _slug(book_part)
        book_row = None
        for b in candidates:
            if _slug(b.get("name")) == target or (_slug(b.get("short_name")) == target and b.get("short_name")):
                book_row = b
                book_code = b.get("book_code")
                break
        # Also allow startswith match for common abbreviations ("rom" -> "romans")
        if not book_row and target:
            for b in candidates:
                if _slug(b.get("name")).startswith(target) or (_slug(b.get("short_name")) and _slug(b.get("short_name")).startswith(target)):
                    book_row = b
                    book_code = b.get("book_code")
                    break

    if not book_row:
        _update_req(req_row, "not_found", "book not found in translation's active canon (or is disabled).", resolved_codes=[bp_norm])
        return {
            "translation": {"code": translation_code, "id": tr_id, "name": tr.get("name"), "language": tr.get("language")},
            "reference": {"input": reference, "found": False, "book": bp_norm},
            "passage": {"verses": [], "text": ""},
            "request": {"id": req_row["id"], "status": "not_found", "latency_ms": int((time.time() - t0) * 1000)},
        }

    book_id = book_row.get("id")
    resolved_codes = [book_code]
    parsed = {"start_chapter": start_ch, "start_verse": start_vs, "end_chapter": end_ch, "end_verse": end_vs}

    # Validate range against known chapter_count (if present)
    cc = book_row.get("chapter_count")
    if isinstance(cc, int) and cc >= 1:
        if start_ch > cc or end_ch > cc:
            _update_req(req_row, "invalid_request", "reference addresses chapter outside the book's chapter_count", resolved_codes=resolved_codes, parsed=parsed)
            return _err("VALIDATION_ERROR", "chapter_number out of range for book", book=book_code, chapter_count=cc)

    # Resolve chapters in range (active only)
    ch_by_num = {}
    for ch in chapters:
        if not isinstance(ch, dict):
            continue
        if ch.get("translation_id") != tr_id or ch.get("book_id") != book_id:
            continue
        if ch.get("status") != "active":
            continue
        cn = ch.get("chapter_number")
        if isinstance(cn, int):
            ch_by_num[cn] = ch

    # Ensure chapters exist for the addressed span (at least start chapter)
    if start_ch not in ch_by_num:
        _update_req(req_row, "not_found", "chapter not found in translation's active canon (or is disabled).", resolved_codes=resolved_codes, parsed=parsed)
        return {
            "translation": {"code": translation_code, "id": tr_id, "name": tr.get("name"), "language": tr.get("language")},
            "reference": {"input": reference, "found": False, "book": book_code, "start": {"chapter": start_ch, "verse": start_vs}, "end": {"chapter": end_ch, "verse": end_vs}},
            "passage": {"verses": [], "text": ""},
            "request": {"id": req_row["id"], "status": "not_found", "latency_ms": int((time.time() - t0) * 1000)},
        }

    # Collect verses within span, active only, enforcing FK consistency (chapter_id must belong to same translation/book and chapter_number must match)
    chapter_ids = {cn: ch_by_num[cn].get("id") for cn in ch_by_num}
    out = []
    verse_ids = []
    for v in verses:
        if not isinstance(v, dict):
            continue
        if v.get("status") != "active":
            continue
        if v.get("translation_id") != tr_id or v.get("book_id") != book_id:
            continue
        cn = v.get("chapter_number")
        if not isinstance(cn, int):
            continue
        # within chapter bounds
        if cn < start_ch or cn > end_ch:
            continue
        # FK: chapter_id must match the chapter in this translation/book, and chapter_number must match
        expected_ch_id = chapter_ids.get(cn)
        if not expected_ch_id:
            continue
        if v.get("chapter_id") != expected_ch_id:
            continue
        vn = v.get("verse_number")
        if not isinstance(vn, int):
            continue
        # verse bounds within edge chapters
        if cn == start_ch and vn < start_vs:
            continue
        if cn == end_ch and vn > end_vs:
            continue
        txt = v.get("text")
        if not isinstance(txt, str) or not txt:
            continue
        out.append(v)

    out.sort(key=lambda r: (r.get("chapter_number", 0), r.get("verse_number", 0)))

    if not out:
        _update_req(req_row, "not_found", "no active verses found for the requested reference range", verse_ids=[], resolved_codes=resolved_codes, parsed=parsed)
        return {
            "translation": {"code": translation_code, "id": tr_id, "name": tr.get("name"), "language": tr.get("language")},
            "reference": {"input": reference, "found": False, "book": book_code, "start": {"chapter": start_ch, "verse": start_vs}, "end": {"chapter": end_ch, "verse": end_vs}},
            "passage": {"verses": [], "text": ""},
            "request": {"id": req_row["id"], "status": "not_found", "latency_ms": int((time.time() - t0) * 1000)},
        }

    # Build formatted passage
    parts = []
    for v in out:
        verse_ids.append(v.get("id"))
        # preserve paragraph breaks as double newline
        if v.get("paragraph_break_before"):
            if parts and not parts[-1].endswith("\n\n"):
                parts.append("\n\n")
        parts.append(str(v.get("text")))
    passage_text = "".join(parts).strip()

    _update_req(req_row, "fulfilled", None, verse_ids=verse_ids, resolved_codes=resolved_codes, parsed=parsed)

    normalized = f"{book_code} {start_ch}:{start_vs}"
    if (end_ch, end_vs) != (start_ch, start_vs):
        if end_ch == start_ch:
            normalized += f"-{end_vs}"
        else:
            normalized += f"-{end_ch}:{end_vs}"

    return {
        "translation": {"code": translation_code, "id": tr_id, "name": tr.get("name"), "language": tr.get("language"), "status": tr.get("status")},
        "reference": {
            "input": reference,
            "normalized": normalized,
            "book": {"code": book_code, "id": book_id, "name": book_row.get("name")},
            "start": {"chapter": start_ch, "verse": start_vs},
            "end": {"chapter": end_ch, "verse": end_vs},
        },
        "passage": {
            "verses": [
                {
                    "id": v.get("id"),
                    "chapter_number": v.get("chapter_number"),
                    "verse_number": v.get("verse_number"),
                    "text": v.get("text"),
                    "paragraph_break_before": v.get("paragraph_break_before"),
                }
                for v in out
            ],
            "text": passage_text,
        },
        "request": {"id": req_row["id"], "status": "fulfilled", "latency_ms": int((time.time() - t0) * 1000), "created_at": req_row.get("created_at")},
    }

def list_bible_translations(status=None, language=None, provider=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0476000" if __import__("os").path.isdir("./environment_mix/0476000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
