            start_after_id = c
            try:
                decoded = base64.b64decode(c.encode("utf-8"), validate=True).decode("utf-8")
                if decoded:
                    start_after_id = decoded
            except Exception:
                start_after_id = c

    # Resolve translation (servable: active or deprecated)
    tr = None
    for t in translations:
        if isinstance(t, dict) and t.get("code") == translation_code and t.get("status") in ("active", "deprecated"):
            tr = t
            break

    req_row = {
        "id": _new_req_id(),
        "request_type": "reference_lookup",
        "translation_code": translation_code,
        "translation_id": tr.get("id") if tr else None,
        "input_reference": None,
        "input_book_ids": None,
        "resolved_book_codes": [book_code],
        "parsed_start_chapter": chapter_number,
        "parsed_start_verse": None,
        "parsed_end_chapter": None,
        "parsed_end_verse": None,
        "result_verse_ids": None,
        "status": "received",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("passage_requests.json", reqs)

    def _finalize(status, error_message=None, verse_ids=None):
        if req_row.get("status") != "received":
            return
        req_row["status"] = status
        req_row["error_message"] = error_message
        req_row["result_verse_ids"] = verse_ids
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("passage_requests.json", reqs)

    if not tr:
        _finalize("not_found", "translation not found or not available")
        return _err("NOT_FOUND", "Translation not found or not available.", translation=translation_code)

    tr_id = tr.get("id")

    book_row = None
    for b in books:
        if isinstance(b, dict) and b.get("translation_id") == tr_id and b.get("book_code") == book_code and b.get("status") == "active":
            book_row = b
            break
    if not book_row:
        _finalize("not_found", "book not found in translation's active canon (or is disabled).")
        return _err("NOT_FOUND", "Book not found in translation's active canon (or is disabled).", translation=translation_code, book=book_code)

    book_id = book_row.get("id")

    # Resolve chapter row (active)
    ch_row = None
    for ch in chapters:
        if not isinstance(ch, dict):
            continue
        if ch.get("translation_id") == tr_id and ch.get("book_id") == book_id and ch.get("chapter_number") == chapter_number and ch.get("status") == "active":
            ch_row = ch
            break
    if not ch_row:
        _finalize("not_found", "chapter not found in translation's active canon (or is disabled).")
        return _err("NOT_FOUND", "Chapter not found in translation's active canon (or is disabled).", translation=translation_code, book=book_code, chapter_number=chapter_number)

    ch_id = ch_row.get("id")

    # Collect active verses for this chapter, enforce FK integrity
    chapter_verses = []
    for v in verses:
        if not isinstance(v, dict):
            continue
        if v.get("status") != "active":
            continue
        if v.get("translation_id") != tr_id or v.get("book_id") != book_id:
            continue
        if v.get("chapter_id") != ch_id:
            continue
        if v.get("chapter_number") != chapter_number:
            continue
        vn = v.get("verse_number")
        if not isinstance(vn, int) or vn < 1:
            continue
        chapter_verses.append(v)

    chapter_verses.sort(key=lambda r: r.get("verse_number", 0))

    # Pagination by verse id order within this already-sorted list
    start_index = 0
    if start_after_id:
        for i, v in enumerate(chapter_verses):
            if v.get("id") == start_after_id:
                start_index = i + 1
                break

    page = chapter_verses[start_index:start_index + limit]
    has_more = (start_index + limit) < len(chapter_verses)
    next_cursor = None
    if has_more and page:
        next_cursor = base64.b64encode(str(page[-1].get("id")).encode("utf-8")).decode("utf-8")

    verse_ids = [v.get("id") for v in page if v.get("id")]
    _finalize("fulfilled", None, verse_ids=verse_ids)

    return {
        "translation": {"code": translation_code, "id": tr_id, "name": tr.get("name"), "language": tr.get("language"), "status": tr.get("status")},
        "book": {"id": book_id, "book_code": book_code, "name": book_row.get("name")},
        "chapter": {"id": ch_id, "chapter_number": chapter_number, "verse_count": ch_row.get("verse_count")},
        "verses": [
            {
                "id": v.get("id"),
                "chapter_number": v.get("chapter_number"),
                "verse_number": v.get("verse_number"),
                "text": v.get("text"),
                "paragraph_break_before": v.get("paragraph_break_before"),
            }
            for v in page
        ],
        "pagination": {"total": len(chapter_verses), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "cursor": cursor},
        "request": {"id": req_row["id"], "status": "fulfilled", "latency_ms": int((time.time() - t0) * 1000)},
    }

def create_passage_request(request_type, translation_code="web", input_reference=None, input_book_ids=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0476000" if __import__("os").path.isdir("./environment_mix/0476000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    translations = _load("translations.json")
    books = _load("books.json")
    chapters = _load("chapters.json")
    verses = _load("verses.json")
    reqs = _load("passage_requests.json")

    def _new_req_id():
        import secrets
        return "breq_" + secrets.token_hex(12)

    # validate request_type
    if request_type not in ("reference", "random"):
        return _err("VALIDATION_ERROR", "request_type must be one of: 'reference', 'random'.")

    if translation_code is None:
        translation_code = "web"
    if not isinstance(translation_code, str) or not translation_code.strip():
        return _err("VALIDATION_ERROR", "translation_code must be a non-empty string.")
    translation_code_norm = translation_code.strip().lower()

    # resolve translation_id if non-disabled exists
    tr = None
    for t in translations:
        if isinstance(t, dict) and t.get("code") == translation_code_norm and t.get("status") in ("active", "deprecated"):
            tr = t
            break

    # Create request in received state (then transition once)
    row = {
        "id": _new_req_id(),
        "request_type": ("reference_lookup" if request_type == "reference" else "random_verse"),
        "translation_code": translation_code_norm,
        "translation_id": tr.get("id") if tr else None,
        "input_reference": (input_reference if request_type == "reference" else None),
        "input_book_ids": (input_book_ids if request_type == "random" else None),
        "resolved_book_codes": None,
        "parsed_start_chapter": None,
        "parsed_start_verse": None,
        "parsed_end_chapter": None,
        "parsed_end_verse": None,
        "result_verse_ids": None,
        "status": "received",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    def _persist_terminal(status, error_message=None, **fields):
        row["status"] = status
        row["error_message"] = error_message
        row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for k, v in fields.items():
            row[k] = v
        reqs.append(row)
        _save("passage_requests.json", reqs)
        return row

    # IMPORTANT: relax prior overly-strict cross-field prohibition.
    # Business rules: reference implies input_reference not null; random implies input_book_ids null or non-empty.
    if request_type == "reference":
        if input_reference is None or not isinstance(input_reference, str) or not input_reference.strip():
            return _persist_terminal("invalid_request", "rule: request_type='reference' requires non-empty input_reference")
        # input_book_ids may be provided by client; ignore it for reference requests (do not reject)
        row["input_reference"] = input_reference
        row["input_book_ids"] = None
    else:  # random
        if input_reference is not None and isinstance(input_reference, str) and input_reference.strip():
            # ignore unexpected input_reference, but record as invalid_request? real service would reject; keep strict here
            return _persist_terminal("invalid_request", "rule: request_type='random' must not include input_reference")
        # input_book_ids may be None OR non-empty string
        if input_book_ids is not None:
            if not isinstance(input_book_ids, str):
                return _persist_terminal("invalid_request", "rule: input_book_ids must be a string when provided")
            if input_book_ids.strip() == "":
                # treated as null per business rule
                row["input_book_ids"] = None
            else:
                row["input_book_ids"] = input_book_ids

    # Attempt immediate resolution
    if tr is None:
        # translation unavailable -> not found (do not expose disabled metadata)
        return _persist_terminal("not_found", "translation not found or disabled", result_verse_ids=[])

    tr_id = tr["id"]

    if request_type == "random":
        # validate and sample similarly to get_random_bible_verse
        raw = row["input_book_ids"]
        scope_testament = None
        resolved_book_codes = None
        if raw is not None:
            upper = raw.strip().upper()
            if upper in ("OT", "NT"):
                scope_testament = upper
            else:
                parts = [p.strip().upper() for p in raw.split(",")]
                if any(p == "" for p in parts):
                    return _persist_terminal("invalid_request", "book_ids contains an empty book code", resolved_book_codes=parts)
                bad = [p for p in parts if not re.fullmatch(r"[A-Z0-9]{2,10}", p or "")]
                if bad:
                    return _persist_terminal("invalid_request", "book_ids contains malformed book code(s): " + ", ".join(bad), resolved_book_codes=parts)
                resolved_book_codes = parts

        books_in_tr = [b for b in books if isinstance(b, dict) and b.get("translation_id") == tr_id and b.get("status") == "active"]
        book_by_code = {b.get("book_code"): b for b in books_in_tr if isinstance(b.get("book_code"), str)}

        eligible_book_ids = set()
        resolved_codes_for_log = None
        if scope_testament in ("OT", "NT"):
            eligible_book_ids = {b["id"] for b in books_in_tr if b.get("testament") == scope_testament}
            resolved_codes_for_log = [b.get("book_code") for b in books_in_tr if b.get("testament") == scope_testament and b.get("book_code")]
        elif resolved_book_codes is not None:
            unknown = [c for c in resolved_book_codes if c not in book_by_code]
            if unknown:
                return _persist_terminal("invalid_request", "unknown book code(s) in list: " + ",".join(unknown), resolved_book_codes=resolved_book_codes)
            eligible_book_ids = {book_by_code[c]["id"] for c in resolved_book_codes}
            resolved_codes_for_log = resolved_book_codes
        else:
            eligible_book_ids = {b["id"] for b in books_in_tr}
            resolved_codes_for_log = [b.get("book_code") for b in books_in_tr if b.get("book_code")]

        eligible_verses = [
            v for v in verses
            if isinstance(v, dict)
            and v.get("translation_id") == tr_id
            and v.get("status") == "active"
            and v.get("book_id") in eligible_book_ids
        ]
        if not eligible_verses:
            return _persist_terminal("not_found", "no eligible verses found", resolved_book_codes=resolved_codes_for_log, result_verse_ids=[])

        chosen = random.choice(eligible_verses)
        return _persist_terminal("fulfilled", None, resolved_book_codes=resolved_codes_for_log, result_verse_ids=[chosen.get("id")])

    # reference resolution (reuse parsing logic similar to get_bible_verse)
    ref = row["input_reference"].strip()
    m = re.match(r"^\s*(?P<book>.+?)\s+(?P<chap>\d+)\s*:\s*(?P<sv>\d+)\s*(?:-\s*(?:(?P<echap>\d+)\s*:\s*)?(?P<ev>\d+)\s*)?$", ref, flags=re.IGNORECASE)
    if not m:
        return _persist_terminal("invalid_request", "could not parse reference: expected 'Book Chapter:Verse' with optional range")
    try:
        sc = int(m.group("chap"))
        sv = int(m.group("sv"))
        ech = m.group("echap")
        evv = m.group("ev")
        ec = int(ech) if ech is not None else None
        ev = int(evv) if evv is not None else None
    except ValueError:
        return _persist_terminal("invalid_request", "could not parse reference: chapter/verse must be integers")
    if sc < 1 or sv < 1 or (ec is not None and ec < 1) or (ev is not None and ev < 1):
        return _persist_terminal("invalid_request", "could not parse reference: chapter/verse must be >= 1", parsed_start_chapter=sc, parsed_start_verse=sv, parsed_end_chapter=ec, parsed_end_verse=ev)
    if ev is None:
        ec = None
    else:
        if ec is None:
            ec = sc
        if (ec < sc) or (ec == sc and ev < sv):
            return _persist_terminal("invalid_request", "could not parse reference: end before start", parsed_start_chapter=sc, parsed_start_verse=sv, parsed_end_chapter=ec, parsed_end_verse=ev)

    book_part = m.group("book").strip()

    # resolve active book by code/name
    books_in_tr = [b for b in books if isinstance(b, dict) and b.get("translation_id") == tr_id and b.get("status") == "active"]
    code_map = {b.get("book_code", "").upper(): b for b in books_in_tr if isinstance(b.get("book_code"), str)}
    name_map = {}
    for b in books_in_tr:
        for nm in (b.get("name"), b.get("short_name")):
            if isinstance(nm, str) and nm.strip():
                key = re.sub(r"[^a-z0-9]+", "", nm.strip().lower())
                if key:
                    name_map[key] = b

    book_row = None
    if book_part.upper() in code_map:
        book_row = code_map[book_part.upper()]
    else:
        key = re.sub(r"[^a-z0-9]+", "", book_part.lower())
        book_row = name_map.get(key)

    resolved_book_codes = [book_row.get("book_code")] if book_row else None

    if book_row is None:
        return _persist_terminal("not_found", "book not found in translation", resolved_book_codes=None, parsed_start_chapter=sc, parsed_start_verse=sv, parsed_end_chapter=ec, parsed_end_verse=ev, result_verse_ids=[])

    # ensure active chapters exist
    chnums = {c.get("chapter_number") for c in chapters if isinstance(c, dict) and c.get("translation_id") == tr_id and c.get("book_id") == book_row.get("id") and c.get("status") == "active"}
    if sc not in chnums or (ec is not None and ec not in chnums):
        return _persist_terminal("not_found", "chapter not found in active canon", resolved_book_codes=resolved_book_codes, parsed_start_chapter=sc, parsed_start_verse=sv, parsed_end_chapter=ec, parsed_end_verse=ev, result_verse_ids=[])

    def in_range(v):
        cn = v.get("chapter_number")
        vn = v.get("verse_number")
        if not isinstance(cn, int) or not isinstance(vn, int):
            return False
        if ec is None:
            return cn == sc and vn == sv
        if cn < sc or cn > ec:
            return False
        if cn == sc and vn < sv:
            return False
        if cn == ec and vn > ev:
            return False
        return True

    selected = [
        v for v in verses
        if isinstance(v, dict)
        and v.get("translation_id") == tr_id
        and v.get("book_id") == book_row.get("id")
        and v.get("status") == "active"
        and in_range(v)
    ]
    selected.sort(key=lambda x: (x.get("chapter_number", 10**9), x.get("verse_number", 10**9)))
    if not selected:
        return _persist_terminal("not_found", "no active verses found for reference", resolved_book_codes=resolved_book_codes, parsed_start_chapter=sc, parsed_start_verse=sv, parsed_end_chapter=ec, parsed_end_verse=ev, result_verse_ids=[])

    return _persist_terminal(
        "fulfilled",
        None,
        resolved_book_codes=resolved_book_codes,
        parsed_start_chapter=sc,
        parsed_start_verse=sv,
        parsed_end_chapter=ec,
        parsed_end_verse=ev,
        result_verse_ids=[v.get("id") for v in selected if v.get("id")]
    )
